ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"update":"SELECT Id,Contact_Id__c,ContactId,Username,EmployeeNumber FROM User where ContactId == null"
}

%dw 2.0
output application/json
---
{
	"update":"select Id,Employee_ID__c,Name,ContactId,EmployeeNumber from contact where Employee_ID__c IN " ++ (vars.emptycontactidusers default "")
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
vars.Finaluserdetails.records map ((item,value)->{
	"Id":item.Id,
	//"Employee_ID__c":item.Employee_ID__c,
	"Contact_External_Id__c":(vars.Finalcontactdetails default [])[?($.EmployeeNumber == item.EmployeeNumber)].ContactId default ""
})

%dw 2.0
output application/json
var systemAdminProfileId = (vars.profileIds filter($.Name == p('sfProfileName.bairdSystemAdministrator'))).Id[0]
var standardUserProfileId = (vars.profileIds filter($.Name == p('sfProfileName.bairdFoundationStandardUser'))).Id[0]
var associateProfileId = (vars.profileIds filter($.Name == p('sfProfileName.bairdAssociate'))).Id[0]
var chatterProfileId = (vars.profileIds filter($.Name == p('sfProfileName.chatterFreeUser'))).Id[0]
fun getPhone(data) = do{
    var AreaCode = data.AreaCode
    var ContactNumber = data.ContactNumber
    ---
    if(data != null  and AreaCode != null and ContactNumber != null) (AreaCode ++ "-" ++ ContactNumber)
    else if(data != null and AreaCode != null and ContactNumber == null) AreaCode
    else if(data != null and AreaCode == null and ContactNumber != null) ContactNumber
    else "#N/A"
}
fun getUserRoleId(item) = if ( !(vars.userEmployeeNumbers.EmployeeNumber contains item.EmpId) or 
		(((vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).UserRoleId[0] == null) or isEmpty((vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId))[0].UserRoleId)) ) calculateUserRoleId(item)
	 else ((vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).UserRoleId[0])
//   else log("WARNING", "WARNING : No Action for UserRoleId field. Field already exists in the target for EmpId: " ++ item.EmpId default "")
fun calculateUserRoleId(item) = if ( vars.salesforceBFSystemAdministrator contains item.EmpId ) (vars.userRoleIds filter($.Name == p('sfUserRole.systemAdministrator'))).Id[0]
	 else if ( vars.salesforceBFStandardUserAdministrator contains item.EmpId ) (vars.userRoleIds filter($.Name == p('sfUserRole.foundationStaff'))).Id[0]	 
	 else if ( vars.licenseType[item.EmpId][0] == "Community" ) (vars.userRoleIds filter($.Name == p('sfUserRole.associate'))).Id[0]
	 else if ( vars.licenseType[item.EmpId][0] == "Chatter" and (vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).UserRoleId[0] == null ) null
	 else do{
	var logWarning = log("WARNING", "Not Eligible for license, Full Name: " ++ item.FirstName default "" ++ " " ++ item.LastName default "")
	---
	null
}
---
vars.validWorkers map((item, index) -> 
	(if ( (vars.userEmployeeNumbers.EmployeeNumber contains item.EmpId) and (((vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).ProfileId[0]) != chatterProfileId) and  !(vars.salesforceBFSystemAdministrator contains item.EmpId) and !(vars.salesforceBFStandardUserAdministrator contains item.EmpId) and (vars.licenseType[item.EmpId][0] == "Chatter") ) {
	// LICENSE_DOWNGRADE_CASE
		"Email": if ( p('api.env') == "PROD" ) (lower((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0])) else (lower(((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) ++ ".invalid")),
		"FederationIdentifier": "#N/A",
		"EmployeeNumber": "#N/A",
		"Alias": "X" ++ item.EmpId,
		"Username": if ( p('api.env') == "PROD" ) ("OLD" ++ lower(((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) default "") ++ "-bairdfoundation")
					else ("OLD" ++ lower(((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) default "") ++ "-bairdfoundation." ++ lower(p('userName.sandboxName'))),
		"ProfileId": (vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).ProfileId[0],
		"CommunityNickname": "OLD" ++ item.UserName,
		"IsActive": false,
		"UserRoleId": (vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).UserRoleId[0]
	}	
	else (
		do{
		var uId = getUserRoleId(item)
		---
		{
			"Email": if ( (p('api.env') == "PROD") and  (uId != null)) (lower((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]))
						// APPEND_.INVALID_FOR_CHATTER_LICENSE_IN_PROD
				else (lower(((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) ++ ".invalid")),
			"FederationIdentifier": item.EmpId,
			"EmployeeNumber": item.EmpId,
			"Alias": item.EmpId,
			"Username": if ( p('api.env') == "PROD" ) (lower(((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) default "") ++ "-bairdfoundation")
						else (lower(((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) default "") ++ "-bairdfoundation." ++ lower(p('userName.sandboxName'))),
			"ProfileId": if ( vars.salesforceBFSystemAdministrator contains item.EmpId ) systemAdminProfileId
						 else if ( vars.salesforceBFStandardUserAdministrator contains item.EmpId ) standardUserProfileId
						 else if ( vars.licenseType[item.EmpId][0] == "Community" ) associateProfileId
						 else chatterProfileId,
			"CommunityNickname": item.UserName,
			"IsActive": item.EmploymentDetail.Active,
			"UserRoleId":
					// NEW USER CASE 	
				if((uId != null) and ((vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId))[0] == null)) uId
					// LICENSE_UPGRADE_CASE FROM CHATTER TO OTHER - DON'T UPDATE USER_ROLE_ID	
				else if ( (uId != null) and ((vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).UserRoleId[0] == null) ) null
		        else uId
		}
	})
) ++ 
//CommonFields
	{

		"FirstName": item.FirstName,
		"LastName": item.LastName,
		"EmailEncodingKey": "ISO-8859-1",
		"TimeZoneSidKey": "America/Chicago",
		"LocaleSidKey": "en_US",
		"LanguageLocaleKey": "en_US",
		"Phone": getPhone((item.Phones filter($.TelecommunicationsNumberTypeCode == "WORK" and $.Type == "Landline"))[0]),
		"Title": item.ProfessionalTitleName default "#N/A",
		"CompanyName": "Baird",
		"Department": item.Department.Name  default "#N/A",
		"Division": if ( item.BusinessUnitOrganization == null or !(vars.businessUnitIds.Baird_BU_ID__c contains item.BusinessUnitOrganization.Descriptor.Id) ) "#N/A" 
			else if ( item.BusinessUnitOrganization.Level <= 2 ) item.BusinessUnitOrganization.Descriptor.Name
			else if	(vars.businessUnitIds.Baird_BU_ID__c contains item.BusinessUnitOrganization.Level2Descriptor.Id)item.BusinessUnitOrganization.Level2Descriptor.Name
			else "#N/A",
		"Street": trim(item.Location.Address1 default "" ++ " " ++ (item.Location.Address2 default "") ++ " " ++ (item.Location.Address3 default "") ++ " " ++ (item.Location.Address4 default "")),
		"City": item.Location.CityName default "#N/A",
		"State": item.Location.StateAbbreviation default "#N/A",
		"PostalCode": item.Location.PostalCode default "#N/A",
		"Country": item.Location.CountryCode default "#N/A",
		"GL_Code__c": item.Department.GlCode default "#N/A",
		"Integration_BU_Name__c": item.BusinessUnitOrganization.Descriptor.Name default "#N/A",
		"Integration_Department_Name__c": item.Department.Name default "#N/A",
		"Integration_Level_2_Name__c": item.BusinessUnitOrganization.Level2Descriptor.Name default "#N/A",
		"Integration_Level_3_Name__c": item.BusinessUnitOrganization.Level3Descriptor.Name default "#N/A",
		"Id": (vars.userEmployeeNumbers filter($.EmployeeNumber == item.EmpId)).Id[0]
	}
)

%dw 2.0
import * from dw::core::Binaries
output application/json
var associateRoleId = (vars.userRoleIds filter($.Name == p('sfUserRole.associate'))).Id[0]
var foundationStaffRoleId = (vars.userRoleIds filter($.Name == p('sfUserRole.foundationStaff'))).Id[0]
var sysAdminRoleId = (vars.userRoleIds filter($.Name == p('sfUserRole.systemAdministrator'))).Id[0]
fun getRole(userRoleId) =
  if (userRoleId == associateRoleId) p('sfUserRole.associate')
  else if (userRoleId == foundationStaffRoleId) p('sfUserRole.foundationStaff')
  else if (userRoleId == sysAdminRoleId) p('sfUserRole.systemAdministrator')
  else userRoleId
var failedRecords = vars.failedRecords map ((item, index)-> {
	"EmployeeNumber": item.originalFields.Alias default null,
	"Name": (item.originalFields.FirstName ++ " " ++ item.originalFields.LastName) default null,
	"Email": item.originalFields.Email default null,
	"UserRoleId": getRole(item.originalFields.UserRoleId),
    "ErrorDescription": ((item.errorMessage default null) replace ( "\<br>") with " ") replace ("\\") with ""
})
---
{
	"to": p('email.supportTeam.to'),
	"subject": p('email.failedUsersRecords.subject') ++ vars.correlationId,
	"body": p('email.failedUsersRecords.body'),
	"cc": p('email.supportTeam.cc'),
	"attachments": [{
		"filename": "FailedRecords.csv",
		"content": toBase64(write(failedRecords,"application/csv")),
		"contentType": "plain/text"
	}]
}
